    <script>
        // Game Constants
        const GRID_SIZE = 30;
        const CELL_SIZE = 20;
        const CANVAS_SIZE = GRID_SIZE * CELL_SIZE;
        const GAME_SPEED = 100;
        const FOOD_COUNT = 5;
        const MAX_SNAKE_LENGTH = 100;

        // Game State
        let canvas, ctx;
        let gameMode = 'pvp';
        let gameLoop = null;
        let isGameOver = false;
        let isPaused = false;
        let scores = { p1: 0, p2: 0 };

        // Snakes: Each snake has body array, direction, current position, color
        let snakes = {
            p1: { body: [], direction: { x: 1, y: 0 }, color: '#4a9eff', nextDirection: { x: 1, y: 0 } },
            p2: { body: [], direction: { x: -1, y: 0 }, color: '#ff4a4a', nextDirection: { x: -1, y: 0 } }
