            document.getElementById('startBtn').addEventListener('click', startGame);
            document.getElementById('restartBtn').addEventListener('click', restartGame);
            document.getElementById('menuBtn').addEventListener('click', showMenu);
        }

        // Handle keyboard input
        function handleKeyDown(e) {
            if (isGameOver) {
                if (e.code === 'Space') {
                    restartGame();
                }
                return;
            }

            // Restart with Space key
            if (e.code === 'Space') {
                if (confirm('Restart the game?')) {
                    restartGame();
                }
                return;
            }

            // Player 1 controls (WASD)
            if (gameMode !== 'cvc' && !snakes.p2.ai) {
                switch(e.code) {
                    case 'KeyW': case 'ArrowUp':
                        if (snakes.p1.direction.y !== 1) {
                            snakes.p1.nextDirection = { x: 0, y: -1 };
                        }
                        break;
                    case 'KeyS': case 'ArrowDown':
                        if (snakes.p1.direction.y !== -1) {
                            snakes.p1.nextDirection = { x: 0, y: 1 };
                        }
                        break;
                    case 'KeyA': case 'ArrowLeft':
                        if (snakes.p1.direction.x !== 1) {
                            snakes.p1.nextDirection = { x: -1, y: 0 };
                        }
                        break;
                    case 'KeyD': case 'ArrowRight':
                        if (snakes.p1.direction.x !== -1) {
                            snakes.p1.nextDirection = { x: 1, y: 0 };
                        }
                        break;
                }
            }

            // Player 2 controls (Arrow keys when not AI)
            if (gameMode !== 'pvc' && !snakes.p1.ai) {
                switch(e.code) {
                    case 'ArrowUp':
                        if (snakes.p2.direction.y !== 1) {
                            snakes.p2.nextDirection = { x: 0, y: -1 };
